import time
import json
import random
from uuid import uuid4
from flask import Flask, send_from_directory, jsonify, g, request

app = Flask(__name__)

# In-memory storage
state = {
    'start': 0,
    'race': {
        'a': {'money': 0, 'bets': {}},
        'b': {'money': 0, 'bets': {}},
    },
    'users': {},
}

def get_user():
    uid = request.cookies.get('uid')
    if not uid or uid not in state['users']:
        uid = str(uuid4())
        state['users'][uid] = {'money': 100}
    return uid

@app.route('/')
def bet_page():
    return send_from_directory('.', 'bet.html')

@app.route('/bet/<int:winner>', methods=['PATCH'])
def send_bet(winner):
    uid = get_user()

    if not winner in [0, 1]:
        return jsonify(success=False, error='Invalid choice')

    winner = ['a', 'b'][winner]

    if uid in state['race']['a']['bets'] or uid in state['race']['b']['bets']:
        return jsonify(success=False, error='Already Bet')

    try:
        bet = int(request.form.get('bet', 0))
    except:
        return jsonify(success=False, error='Invalid Bet Amount')

    if bet <= 0:
        return jsonify(success=False, error='Invalid Bet Amount')

    money = state['users'][uid]['money']
    bet = min(bet, money)
    bet = min(bet, 1000000)

    state['race'][winner]['bets'][uid] = bet
    state['race'][winner]['money'] += bet
    state['users'][uid]['money'] -= bet

    return jsonify(success=True)

def calc_odds():
    a_sum = state['race']['a']['money']
    b_sum = state['race']['b']['money']

    if a_sum == 0: a_sum = 1
    if b_sum == 0: b_sum = 1

    a_odds = a_sum / float(b_sum)
    b_odds = b_sum / float(a_sum)

    return a_odds, b_odds, a_sum, b_sum

@app.route('/check')
def get_money():
    uid = get_user()
    now = int(time.time())

    if state['start'] == 0:
        state['start'] = now + 35

    if now > state['start']:
        a_odds, b_odds, a_sum, b_sum = calc_odds()
    else:
        a_odds, b_odds, a_sum, b_sum = 0, 0, 0, 0

    side = None
    bet = 0
    if uid in state['race']['a']['bets']:
        side = 0
        bet = state['race']['a']['bets'][uid]
    elif uid in state['race']['b']['bets']:
        side = 1
        bet = state['race']['b']['bets'][uid]

    return jsonify(
        a=a_odds, b=b_odds,
        a_sum=a_sum, b_sum=b_sum,
        bet=bet,
        side=side,
        money=state['users'][uid]['money'],
        start=state['start']
    )

@app.route('/flag1')
def flag1():
    uid = get_user()
    if state['users'][uid]['money'] < 250000:
        return jsonify(success=False, error='Not enough money')
    return jsonify(success=True, flag='flag{test_flag_1}')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8000)

